.chapter-page article h2{position:relative;display:block;padding:var(--space-3) var(--space-4) var(--space-3) calc(var(--space-4) + 10px + var(--space-2));background:var(--primary-50);border-radius:var(--radius-md);line-height:var(--lh-heading);word-break:keep-all;overflow-wrap:anywhere}
.chapter-page article h2::before{position:absolute;left:var(--space-4);top:calc(var(--space-3) + .1em)}
